def solve(matrix):
    n = len(matrix)
    if n == 0:
        return 1

    # Make a copy to allow row reduction without modifying input
    m = [row[:] for row in matrix]
    det = 1
    sign = 1

    for i in range(n):
        # Find pivot row
        pivot = -1
        for k in range(i, n):
            if m[k][i] != 0:
                pivot = k
                break
        if pivot == -1:
            return 0
        if pivot != i:
            m[i], m[pivot] = m[pivot], m[i]
            sign = -sign

        det *= m[i][i]

        # Eliminate below
        for k in range(i + 1, n):
            if m[k][i] != 0:
                # m[k][j] = m[k][j] * pivot - m[i][j] * m[k][i]
                factor = m[k][i]
                for j in range(i, n):
                    m[k][j] = m[k][j] * m[i][i] - m[i][j] * factor
                # The m[i][i] is now factored out from row k, but we keep m[i][i] as pivot
                # Det adjust: row k was modified by pivot, but we factored out pivot once per row
                # Actually we need integer arithmetic carefully
    return sign * det


def _det_naive(matrix):
    n = len(matrix)
    if n == 0:
        return 1
    if n == 1:
        return matrix[0][0]
    total = 0
    for j in range(n):
        minor = [row[:j] + row[j+1:] for row in matrix[1:]]
        total += ((-1) ** j) * matrix[0][j] * _det_naive(minor)
    return total


def solve(matrix):
    # Use cofactor expansion - this is O(n!) but works for small n
    return _det_naive(matrix)

