from fractions import Fraction


def solve(matrix):
    n = len(matrix)
    if n == 0:
        return 1

    # Use LU-decomposition with Fraction for exact integer arithmetic
    m = [[Fraction(matrix[i][j]) for j in range(n)] for i in range(n)]
    det = Fraction(1)
    sign = 1

    for i in range(n):
        # Find pivot
        pivot = -1
        for k in range(i, n):
            if m[k][i] != 0:
                pivot = k
                break
        if pivot == -1:
            return 0
        if pivot != i:
            m[i], m[pivot] = m[pivot], m[i]
            sign = -sign

        det *= m[i][i]

        # Eliminate below
        for k in range(i + 1, n):
            if m[k][i] != 0:
                factor = m[k][i] / m[i][i]
                for j in range(i, n):
                    m[k][j] -= factor * m[i][j]

    result = sign * det
    # Should be integer
    assert result.denominator == 1
    return int(result)

