from fractions import Fraction

def solve(m):
    n = len(m)
    if n == 0:
        return 1
    A = [list(map(Fraction, row)) for row in m]
    det = Fraction(1)
    for i in range(n):
        pivot = -1
        for k in range(i, n):
            if A[k][i] != 0:
                pivot = k
                break
        if pivot == -1:
            return 0
        if pivot != i:
            A[i], A[pivot] = A[pivot], A[i]
            det = -det
        det *= A[i][i]
        for k in range(i + 1, n):
            if A[k][i] == 0:
                continue
            factor = A[k][i] / A[i][i]
            for j in range(i, n):
                A[k][j] -= factor * A[i][j]
    return int(det)

