def solve(year, month, day):
    import datetime
    if 1 <= year <= 9999:
        try:
            return datetime.date(year, month, day).strftime('%A')
        except Exception:
            pass
    # Proleptic Gregorian for any integer year via 400-year cycle shift
    # Gregorian calendar repeats every 400 years (146097 days, multiple of 7)
    # Shift year into [2000, 2399] preserving leapness (mod 400 preserves it)
    y = year
    # bring into range 2000..2399
    # compute offset k so that y + k*400 in range
    # use modulo
    shifted = 2000 + ((y - 2000) % 400)
    d = datetime.date(shifted, month, day)
    return d.strftime('%A')

